"use client";

import { DoadorProvider } from "./contexts/DoadorContext";
import { BeneficiarioProvider } from "./contexts/BeneficiarioContext";
import "./globals.css";

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="pt-BR">
      <body>
        {/* Envolvemos toda a aplicação com os dois Providers */}
        <DoadorProvider>
          <BeneficiarioProvider>
            {children}
          </BeneficiarioProvider>
        </DoadorProvider>
      </body>
    </html>
  );
}
